# name: multi_set_size_trend
# description: Yes rate on 2-example sets minus yes rate on 4-example sets; observed > null means people narrow their generalization with more examples more than the model does (model under-produces the size-principle tightening), observed < null the reverse.
def test_statistic(df):
    n = df["number_set"].astype(str).str.count(",").values + 1
    r = df["rating"].astype(float).values
    a = n == 2
    b = n == 4
    if a.sum() == 0 or b.sum() == 0:
        return 0.0
    return float(r[a].mean() - r[b].mean())

# name: shared_digit_match_yes
# description: Among multi-example sets whose examples all share a final digit, yes rate on targets that also end in that digit (excluding targets that are themselves examples); observed > null means the model under-produces endorsement of a visible final-digit rule, observed < null over-produces it.
def test_statistic(df):
    s = df["number_set"].astype(str)
    u, inv = np.unique(s.values, return_inverse=True)
    dig = np.full(len(u), -1)
    for i, x in enumerate(u):
        ex = [int(v) for v in x.split(",")]
        ds = {v % 10 for v in ex}
        if len(ex) >= 2 and len(ds) == 1:
            dig[i] = ds.pop()
    d = dig[inv]
    t = df["target"].astype(int).values
    r = df["rating"].astype(float).values
    sel = (d >= 0) & (t % 10 == d)
    if sel.sum() == 0:
        return 0.0
    return float(r[sel].mean())
